class OfflineDatabaseUnavailable extends Error {
  constructor() {
    super('PostgreSQL is intentionally disabled in the Assistant Headless Runtime.');
    this.code = 'OFFLINE_RUNTIME_DATABASE_DISABLED';
  }
}
class Pool {
  constructor() { this.options = {}; }
  async query() { throw new OfflineDatabaseUnavailable(); }
  async connect() { throw new OfflineDatabaseUnavailable(); }
  async end() {}
}
class Client {
  constructor() { this.options = {}; }
  async connect() { throw new OfflineDatabaseUnavailable(); }
  async query() { throw new OfflineDatabaseUnavailable(); }
  async end() {}
}
module.exports = { Pool, Client };
